def weekday_for_date(year_value, month_value, day_value):
    adjusted_year, adjusted_month = year_value, month_value
    if adjusted_month < 3:
        adjusted_month += 12
        adjusted_year -= 1
    weekday_index = (day_value + (13 * (adjusted_month + 1)) // 5 + adjusted_year % 100 + (adjusted_year % 100) // 4 + (adjusted_year // 100) // 4 + 5 * (adjusted_year // 100)) % 7
    return ['saturday', 'sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday'][weekday_index]
