def scan_quantities(text_value):
    scanned = str(text_value).lower().replace('half an hour', '0.5 hour').replace('half hour', '0.5 hour').replace('an hour', '1 hour')
    quantities = []
    position = 0
    while position < len(scanned):
        if scanned[position].isdigit():
            number_end = position
            decimal_seen = False
            while number_end < len(scanned) and (scanned[number_end].isdigit() or (scanned[number_end] == '.' and not decimal_seen)):
                decimal_seen = decimal_seen or scanned[number_end] == '.'
                number_end += 1
            number = float(scanned[position:number_end])
            unit_start = number_end
            while unit_start < len(scanned) and (scanned[unit_start].isspace() or scanned[unit_start] in '-–—'):
                unit_start += 1
            unit_end = unit_start
            while unit_end < len(scanned) and scanned[unit_end].isalpha():
                unit_end += 1
            if unit_end > unit_start:
                quantities.append((number, scanned[unit_start:unit_end]))
            position = max(number_end, unit_end)
        else:
            position += 1
    return quantities
def seconds_from_text(text_value):
    total = 0.0
    for number, unit in scan_quantities(text_value):
        if unit in {'h', 'hr', 'hrs', 'hour', 'hours'}:
            total += number * 3600
        elif unit in {'m', 'min', 'mins', 'minute', 'minutes'}:
            total += number * 60
        elif unit in {'s', 'sec', 'secs', 'second', 'seconds'}:
            total += number
    return total
