def parse_clock(token, following_token=''):
    candidate = (token + following_token).lower()
    candidate = ''.join(character for character in candidate if character.isdigit() or character == ':' or character.isalpha())
    suffix = 'am' if candidate.endswith('am') else ('pm' if candidate.endswith('pm') else '')
    if not suffix:
        return None
    core = candidate[:-2]
    pieces = core.split(':')
    if not pieces[0].isdigit() or (len(pieces) > 1 and not pieces[1].isdigit()):
        return None
    hour_value = int(pieces[0])
    minute_value = int(pieces[1]) if len(pieces) > 1 else 0
    if not 1 <= hour_value <= 12 or not 0 <= minute_value < 60:
        return None
    return (hour_value % 12 + (12 if suffix == 'pm' else 0)) * 60 + minute_value
